import json,re,collections;d=json.load(open('inputs.json'))
ids=collections.defaultdict(list)
for x in d['documents']:
    for m in re.findall(r'PX-\d{4}', x['text']): ids[m].append(x['doc_id'])
s=sorted(ids)
print(len(s)); print(s[0],s[-1])
missing=[f'PX-{i:04d}' for i in range(560,960) if f'PX-{i:04d}' not in ids]
print('missing in 0560-0959:',len(missing), missing)
print(collections.Counter(len(v) for v in ids.values()))

